use tokio::sync::mpsc;

let (tx, mut rx) = mpsc::channel::<Order>(1024);   // bounded: backpressure built in
tokio::spawn(async move {
    while let Some(order) = rx.recv().await { handle(order).await }
});

tx.send(order).await?;                             // awaits when the buffer is full
